private fun sampleSizeFor(width: Int, height: Int): Int {
    var sample = 1
    var longEdge = maxOf(width, height)
    while (longEdge / 2 >= MAX_EDGE_PX) {
        longEdge /= 2
        sample *= 2
    }
    return sample
}

