#!/usr/bin/env python3
"""
Exports the Claude Code session transcript to a single readable JSON file.

The raw transcript is JSONL and carries harness bookkeeping plus base64 image payloads
(the assignment PDF, the face photos read during model validation). Those are stripped:
images are replaced by a short placeholder, and only conversational records are kept.
"""
import json, sys, os

SKIP_TYPES = {
    "mode", "permission-mode", "atis-latch", "last-prompt",
    "ai-title", "queue-operation", "file-history-snapshot",
}
MAX_TEXT = 20000  # truncate very long tool outputs


def clean(block):
    """Normalise one content block, dropping binary payloads."""
    if not isinstance(block, dict):
        return {"type": "text", "text": str(block)[:MAX_TEXT]}

    kind = block.get("type")

    if kind == "image":
        src = block.get("source", {})
        return {"type": "image", "note": f"<image omitted: {src.get('media_type', 'unknown')}>"}

    if kind == "text":
        return {"type": "text", "text": (block.get("text") or "")[:MAX_TEXT]}

    if kind == "thinking":
        return {"type": "thinking", "text": (block.get("thinking") or "")[:MAX_TEXT]}

    if kind == "tool_use":
        return {
            "type": "tool_use",
            "name": block.get("name"),
            "input": json.loads(json.dumps(block.get("input", {}), default=str)[:MAX_TEXT] or "{}")
            if len(json.dumps(block.get("input", {}), default=str)) <= MAX_TEXT
            else {"_truncated": json.dumps(block.get("input", {}), default=str)[:MAX_TEXT]},
        }

    if kind == "tool_result":
        content = block.get("content")
        if isinstance(content, list):
            content = [clean(c) for c in content]
        elif isinstance(content, str):
            content = content[:MAX_TEXT]
        return {"type": "tool_result", "is_error": block.get("is_error", False), "content": content}

    return {"type": kind or "unknown"}


def main(src, dst):
    messages = []
    for line in open(src):
        line = line.strip()
        if not line:
            continue
        try:
            rec = json.loads(line)
        except json.JSONDecodeError:
            continue
        if rec.get("type") in SKIP_TYPES:
            continue
        msg = rec.get("message")
        if not isinstance(msg, dict):
            continue

        content = msg.get("content")
        if isinstance(content, str):
            content = [{"type": "text", "text": content[:MAX_TEXT]}]
        elif isinstance(content, list):
            content = [clean(b) for b in content]
        else:
            continue

        messages.append({
            "role": msg.get("role", rec.get("type")),
            "timestamp": rec.get("timestamp"),
            "content": content,
        })

    out = {
        "project": "Android Attendance App — hiring assignment",
        "tool": "Claude Code",
        "session_id": os.path.basename(src).replace(".jsonl", ""),
        "message_count": len(messages),
        "note": "Image payloads (assignment PDF, face photos used for model validation) "
                "are omitted; long tool outputs are truncated.",
        "messages": messages,
    }
    with open(dst, "w") as f:
        json.dump(out, f, indent=2, ensure_ascii=False)
    print(f"{len(messages)} messages -> {dst} ({os.path.getsize(dst)/1e6:.1f} MB)")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
